{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.d2p_tool_transformed_dates AS WITH base_data AS ( SELECT *, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', CASE WHEN design_approval_sent = 1751179296000 THEN NULL ELSE TO_TIMESTAMP((design_approval_sent / 1000)::INTEGER) END ) AS design_approved_monica_time, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', TO_TIMESTAMP((created_at_1 / 1000)::INTEGER)) AS design_created_time, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', TO_TIMESTAMP((pd_acceptance_time / 1000)::INTEGER)) AS pd_acceptance_time_, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', COALESCE( TO_TIMESTAMP(TRY_TO_NUMBER(EXPECTED_DELIVERED_DATE) / 1000), TRY_TO_TIMESTAMP(EXPECTED_DELIVERED_DATE) ) ) AS expected_delivered_date_, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', TO_TIMESTAMP((design_approval_recieved / 1000)::INTEGER)) AS design_approved_Sid_time, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', TO_TIMESTAMP((last_updated_at / 1000)::INTEGER)) AS last_updated_at_ist, CONVERT_TIMEZONE(\'UTC\', \'Asia/Kolkata\', TO_TIMESTAMP((EDIT_TIMESTAMP / 1000)::INTEGER)) AS edit_timestamp_ist, TRY_TO_TIMESTAMP(TP_UPDATED_TIMESTAMP, \'YYYY-MM-DD\') AS tp_updated_timestamp_, TRY_TO_TIMESTAMP(fabric_sample_sourcing, \'MON DD, YYYY HH12:MI AM\') AS fabric_sample_sourcing_design_time, TRY_TO_TIMESTAMP(fabric_sample_received_production, \'MON DD, YYYY HH12:MI AM\') AS proto_received_production_time, TRY_TO_TIMESTAMP(sample_given_back_to_design, \'MON DD, YYYY HH12:MI AM\') AS proto_given_back_to_design_time, TRY_TO_TIMESTAMP(fabric_reference_prod_time, \'MON DD, YYYY HH12:MI AM\') AS fabric_reference_production_time, sku_group AS sku, REGEXP_SUBSTR_ALL(C1, \'[A-Z][a-z]{2}\\s+\\d{1,2},\\s+\\d{4}\\s+\\d{1,2}:\\d{2}\\s+[AaPp][Mm]\') AS c1_dates_array, REGEXP_SUBSTR_ALL(C2, \'[A-Z][a-z]{2}\\s+\\d{1,2},\\s+\\d{4}\\s+\\d{1,2}:\\d{2}\\s+[AaPp][Mm]\') AS c2_dates_array FROM SNITCH_DB.MAPLEMONK.xano_d2p_updated_202512_get_design_production_info ), transformed_data_d2p AS ( SELECT *, TRY_TO_TIMESTAMP( TRIM(c1_dates_array[ARRAY_SIZE(c1_dates_array)-1]), \'MON DD, YYYY HH12:MI AM\' ) AS original_date_proto_received_production_time, TRY_TO_TIMESTAMP( TRIM(c1_dates_array[ARRAY_SIZE(c1_dates_array)-2]), \'MON DD, YYYY HH12:MI AM\' ) AS revised_date_1_proto_received_production_time, TRY_TO_TIMESTAMP( TRIM(c1_dates_array[ARRAY_SIZE(c1_dates_array)-3]), \'MON DD, YYYY HH12:MI AM\' ) AS revised_date_2_fabric_sample_received_prod, TRY_TO_TIMESTAMP( TRIM(c2_dates_array[ARRAY_SIZE(c2_dates_array)-1]), \'MON DD, YYYY HH12:MI AM\' ) AS original_date_proto_given_back_to_design_time, TRY_TO_TIMESTAMP( TRIM(c2_dates_array[ARRAY_SIZE(c2_dates_array)-2]), \'MON DD, YYYY HH12:MI AM\' ) AS revised_date_1_proto_given_back_to_design_time, TRY_TO_TIMESTAMP( TRIM(c2_dates_array[ARRAY_SIZE(c2_dates_array)-3]), \'MON DD, YYYY HH12:MI AM\' ) AS revised_date_2_proto_given_back_to_design_time FROM base_data ), data_with_latest_timestamp AS ( SELECT *, GREATEST( COALESCE(design_created_time, \'1970-01-01\'), COALESCE(design_approved_monica_time, \'1970-01-01\'), COALESCE(design_approved_Sid_time, \'1970-01-01\'), COALESCE(pd_acceptance_time_, \'1970-01-01\'), COALESCE(fabric_approval_sid_time, \'1970-01-01\'), COALESCE(fabric_sample_sourcing_design_time, \'1970-01-01\'), COALESCE(proto_received_production_time, \'1970-01-01\'), COALESCE(proto_given_back_to_design_time, \'1970-01-01\'), COALESCE(fabric_reference_production_time, \'1970-01-01\') ) AS last_update_timestamp FROM transformed_data_d2p ) SELECT *, CASE WHEN LOWER(PD_ACCEPTANCE_STATUS) LIKE \'%job work%\' OR LOWER(comments) LIKE \'%job work%\' THEN CASE WHEN expected_delivered_date_ IS NOT NULL THEN \'Job Work : Inward Pending\' WHEN proto_received_production_time IS NOT NULL THEN \'Job Work : Order Place Pending\' ELSE \'Job Work : Proto Receival Pending\' END WHEN expected_delivered_date_ IS NOT NULL THEN \'Inward Pending\' WHEN LOWER(PD_ACCEPTANCE_STATUS) = \'rejected\' THEN \'PD Rejected\' WHEN LOWER(PD_ACCEPTANCE_STATUS) LIKE \'%hold%\' THEN \'PD On Hold\' WHEN proto_received_production_time IS NOT NULL AND expected_delivered_date_ IS NULL THEN \'Order Place Pending\' WHEN LOWER(PD_ACCEPTANCE_STATUS) = \'accepted\' AND proto_received_production_time IS NULL THEN \'Proto Receival Pending\' WHEN techpack_link LIKE \'%http%\' AND (PD_ACCEPTANCE_STATUS IS NULL OR PD_ACCEPTANCE_STATUS = \'\') THEN \'PD Acceptance Pending\' WHEN techpack_link NOT LIKE \'%http%\' OR techpack_link IS NULL THEN \'Tech Pack Link Pending\' ELSE \'Stage Not Defined\' END AS stage FROM data_with_latest_timestamp; CREATE OR REPLACE TABLE snitch_db.maplemonk.d2p_tool_transformed_dates2 AS WITH sku_groups AS ( SELECT lfim.*, REGEXP_REPLACE(lfim.SKU, \'-[^-]*$\', \'\') AS new_sku_group, ROW_NUMBER() OVER ( PARTITION BY REGEXP_REPLACE(lfim.SKU, \'-[^-]*$\', \'\') ORDER BY lfim.SKU ) AS rn_rownum FROM logic_final_item_master lfim QUALIFY rn_rownum = 1 ) , moq_data AS ( SELECT REGEXP_REPLACE(SKU, \'-[^-]*$\', \'\') AS new_sku_group, SUM(TOTAL_QTY) AS MOQ select * FROM SNITCH_DB.MAPLEMONK.PURCHASE_ORDER_JOURNEY GROUP BY 1 ) SELECT t.sku_group AS sku_group_d2p, t.expected_delivered_date as expected_delivered_date_d2p, s.new_sku_group as sku_group_logic, s.*, t.stage, m.new_sku_group as sku_group_moq_data, COALESCE(m.MOQ, 0) AS MOQ FROM d2p_tool_transformed_dates t LEFT JOIN sku_groups s ON t.sku_group = s.new_sku_group LEFT JOIN moq_data m ON t.sku_group = m.new_sku_group",
                    "transaction": true
                }
            ) }}
